import React from 'react';

const Answer = ({
  question, // string
  options, // array of strings
  selectedAnswer, // index of selected answer
  correctAnswer, // string
  hint, // string
  explanation, // string
  difficulty, // string
  subject, // string
  topic, // string
}) => {
  return (
    <div className="bg-white rounded-lg p-6 mb-8 shadow-lg border border-gray-300 max-w-3xl mx-auto">
      {/* Question */}
      <div className="mb-6">
        <h3 className="text-2xl font-semibold text-gray-800">Question:</h3>
        <p className="text-lg text-gray-600 mt-2">{question}</p>
      </div>

      {/* Options */}
      <div className="mb-6">
        <h4 className="text-xl font-semibold text-gray-800">Options:</h4>
        <ul className="mt-4 space-y-3">
          {options?.map((option, index) => (
            <li
              key={index}
              className={`px-4 py-2 rounded-lg cursor-pointer transition-all duration-200 ease-in-out border ${
                option === options[selectedAnswer]
                  ? option === correctAnswer
                    ? 'bg-green-100 border-green-500 text-green-600'
                    : 'bg-red-100 border-red-500 text-red-600'
                  : option === correctAnswer
                  ? 'bg-green-50 border-green-400 text-green-500'
                  : 'bg-gray-100 border-gray-300 text-gray-700'
              }`}
            >
              {index + 1}. {option}
            </li>
          ))}
        </ul>
      </div>

      {/* Correct Answer */}
      <div className="mb-6">
        <span className="font-semibold text-gray-800">Correct Answer: </span>
        <span className="text-green-600">{correctAnswer || 'Not provided'}</span>
      </div>

      {/* Feedback on the selected answer */}
      {selectedAnswer !== undefined ? 
        <div className={`font-semibold mt-4 text-xl ${options[selectedAnswer] === correctAnswer ? 'text-green-600' : 'text-red-600'}`}>
          {options[selectedAnswer] === correctAnswer ? 'Correct!' : 'Incorrect'}
        </div> : <div>Not Attempted</div>
      }

      {/* Hint Section */}
      {hint && (
        <div className="mt-6 bg-blue-50 p-4 rounded-lg border-l-4 border-blue-500">
          <h4 className="font-semibold text-lg text-gray-800">Hint:</h4>
          <p className="text-gray-700">{hint}</p>
        </div>
      )}

      {/* Explanation Section */}
      {explanation && (
        <div className="mt-6 bg-yellow-50 p-4 rounded-lg border-l-4 border-yellow-500">
          <h4 className="font-semibold text-lg text-gray-800">Explanation:</h4>
          <p className="text-gray-700">{explanation}</p>
        </div>
      )}

      {/* Additional Info */}
      <div className="mt-6 grid grid-cols-1 sm:grid-cols-2 gap-6">
        <div>
          <span className="font-semibold text-gray-800">Difficulty: </span>
          <span className="text-gray-600 capitalize">{difficulty || 'Unknown'}</span>
        </div>
        <div>
          <span className="font-semibold text-gray-800">Subject: </span>
          <span className="text-gray-600">{subject || 'N/A'}</span>
        </div>
        <div>
          <span className="font-semibold text-gray-800">Topic: </span>
          <span className="text-gray-600">{topic || 'N/A'}</span>
        </div>
      </div>
    </div>
  );
};

export default Answer;
